sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
	// g_form.setValue('equipment_guidance', 'onChange is working!');

   if (isLoading || newValue === '') {
	g_form.clearValue('equipment_guidance');
      return;
   }
if(newValue == 'laptop'){
	g_form.setValue('equipment_guidance',
            'Keep the laptop secure and return it with its charger.'
        );
    } else if (newValue == 'desktop') {
        g_form.setValue('equipment_guidance',
            'Return the monitor with all supplied cables and accessories.'
        );
    } else if (newValue == 'mobile') {
        g_form.setValue(
            'equipment_guidance',
            'Protect the mobile device and return it with its charger and accessories.'
        ); 
		} else {
        g_form.clearValue('equipment_guidance');
	}
	}
